CREATE OR REPLACE FUNCTION public.task_blocker_track() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid;pid uuid;nm text;kind text;active_block boolean;approved timestamptz;BEGIN
kind:=CASE WHEN TG_TABLE_NAME='client_tasks' THEN 'launch' ELSE 'recurring' END;
IF kind='launch' THEN cid:=NEW.client_id; SELECT id INTO pid FROM pipelines WHERE code=NEW.pipeline_code;nm:=NEW.name;ELSE SELECT cp.client_id,cp.pipeline_id,i.name||' · '||NEW.stage INTO cid,pid,nm FROM activity_plans p JOIN client_pipelines cp ON cp.id=p.client_pipeline_id JOIN activity_items i ON i.id=NEW.item_id WHERE p.id=NEW.plan_id;END IF;
active_block:=NEW.status IN('blocked','waiting_client');
IF TG_OP='INSERT' THEN IF NEW.backup_id IS NULL AND pid IS NOT NULL THEN NEW.backup_id:=pipeline_default_backup(pid);END IF;IF active_block THEN NEW.blocked_since:=now();END IF;
ELSE IF NEW.blocked_since IS DISTINCT FROM OLD.blocked_since AND auth.uid() IS NOT NULL AND coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Blocker timing is managed by the system';END IF;IF active_block AND OLD.status NOT IN('blocked','waiting_client') THEN NEW.blocked_since:=now();NEW.escalation_level:=0;NEW.last_escalated_at:=NULL;ELSIF NOT active_block THEN NEW.blocked_since:=NULL;END IF;END IF;
IF NEW.status='waiting_client' THEN NEW.blocker_reason:='Waiting on client approval';END IF;
IF active_block AND coalesce(btrim(NEW.blocker_reason),'')='' THEN NEW.blocker_reason:='Other blocker';END IF;IF active_block AND NEW.blocked_since IS NULL THEN NEW.blocked_since:=now();END IF;
IF active_block AND NEW.blocker_reason='Waiting on client approval' THEN
 IF kind='launch' THEN IF NOT NEW.requires_client_approval THEN RAISE EXCEPTION 'This task does not require client approval';END IF;ELSIF NEW.stage<>'approval' THEN RAISE EXCEPTION 'Only the approval stage may wait for client approval';END IF;
 IF coalesce(btrim(NEW.blocker_impact),'')='' THEN NEW.blocker_impact:='Progress on '||nm||' is paused until the required approval is received.';END IF;
 INSERT INTO task_approval_blockers(task_kind,task_id,client_id,pipeline_id,task_name,impact,blocked_since) VALUES(kind,NEW.id,cid,pid,nm,NEW.blocker_impact,NEW.blocked_since) ON CONFLICT(task_kind,task_id,blocked_since) DO UPDATE SET impact=excluded.impact;
END IF;
IF kind='launch' THEN approved:=NEW.client_approved_at;IF approved IS NOT NULL THEN UPDATE task_approval_blockers SET owner_approved_at=coalesce(owner_approved_at,approved) WHERE task_kind=kind AND task_id=NEW.id AND resolved_at IS NULL;END IF;END IF;RETURN NEW;END $$;
ALTER TABLE public.pipeline_members ADD COLUMN backup_id uuid REFERENCES public.profiles(id);
CREATE OR REPLACE FUNCTION public.pipeline_backup_default() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.backup_id IS NULL THEN NEW.backup_id:=pipeline_default_backup(NEW.pipeline_id);END IF; RETURN NEW;END $$;
CREATE TRIGGER pipeline_backup_default BEFORE INSERT ON public.pipeline_members FOR EACH ROW EXECUTE FUNCTION public.pipeline_backup_default();
REVOKE ALL ON FUNCTION public.pipeline_backup_default() FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.set_pipeline_backup(_member uuid,_backup uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p uuid;BEGIN PERFORM activity_require_ready();SELECT pipeline_id INTO p FROM pipeline_members WHERE id=_member;IF NOT is_pipeline_head(auth.uid(),p) THEN RAISE EXCEPTION 'Pipeline Head only';END IF;IF NOT EXISTS(SELECT 1 FROM pipeline_members m JOIN profiles pr ON pr.id=m.user_id AND pr.status='active' WHERE m.pipeline_id=p AND m.user_id=_backup AND m.active) THEN RAISE EXCEPTION 'Choose an active pipeline member';END IF;UPDATE pipeline_members SET backup_id=_backup WHERE id=_member;END $$;
REVOKE ALL ON FUNCTION public.set_pipeline_backup(uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.set_pipeline_backup(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.process_stage3_blockers() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN RETURN escalate_blocked_tasks()+queue_blocker_reminders();END $$;
REVOKE ALL ON FUNCTION public.process_stage3_blockers() FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.process_stage3_blockers() TO service_role;
CREATE OR REPLACE FUNCTION public.scorecard_member_reports(_person uuid,_month date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN PERFORM activity_require_ready();IF NOT scorecard_can_view(_person) THEN RAISE EXCEPTION 'Scorecard not available';END IF;RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'status',r.status,'clients',jsonb_build_object('hotel_name',c.hotel_name),'client_pipelines',jsonb_build_object('pipelines',jsonb_build_object('name',p.name)))) FROM monthly_reports r JOIN clients c ON c.id=r.client_id JOIN client_pipelines cp ON cp.id=r.client_pipeline_id JOIN pipelines p ON p.id=cp.pipeline_id WHERE r.created_by=_person AND r.month=date_trunc('month',_month)::date AND NOT c.is_test AND NOT c.is_demo AND (is_manager(auth.uid()) OR has_role(auth.uid(),'bd_manager') OR has_role(auth.uid(),'hr') OR _person=auth.uid() OR is_pipeline_head(auth.uid(),cp.pipeline_id))),'[]');END $$;
REVOKE ALL ON FUNCTION public.scorecard_member_reports(uuid,date) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.scorecard_member_reports(uuid,date) TO authenticated,service_role;